#!/usr/bin/env python3
from __future__ import annotations

import base64
import gzip
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
BUNDLE = json.loads('{"viajes/index.v3.html":"","viajes/css/app.css":"","viajes/js/core.js":"","viajes/js/trip-calculator.js":"","viajes/js/ui.js":"","viajes/js/app.js":"","viajes/scripts/build_v3_contract.py":"","viajes/scripts/validate_phase1.py":"","viajes/data/schema-v3.json":"","viajes/docs/PHASE_0_AUDIT.md":"","viajes/docs/ARCHITECTURE_V3.md":"","viajes/docs/OPERATIONS_PHASE1.md":""}')

for relative_path, encoded in BUNDLE.items():
    path = ROOT / relative_path
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(gzip.decompress(base64.b64decode(encoded)))

print(f"Installed {len(BUNDLE)} Phase 0/1 files")
